        const suffix = scenario.name.startsWith('Forced colors') ? 'forced' : 'normal'
        const wanted =
          'UI-CASCADE:' +
          scenario.parameters.scheme +
          ':' +
          scenario.parameters.theme +
          ':' +
          suffix
        if (entry.testName !== wanted) errors.push('Missing matrix example binding ' + entry.id)
      }
    } else if (
      entry.phase !== 'future' ||
      !entry.owner ||
      !entry.reason ||
      entry.file ||
      entry.testName
    )
